// th16_s3_w03 — TH16 v1.00a Stage 3 道中 第 3 波（两轮 ECir00 圆周编队）
// 源：st03.ecl.txt MainSub02:1212-1240（排程）、ECir00:8-43、ECir00_at:45-107
const TH16_BALL: int = 416;

const TIME_LIMIT: int = 1524;
const OPENING_BUFFER: int = 120;
const SPAWN_COUNT: int = 32;
const SPAWN_GAP: int = 10;
const GROUP_GAP: int = 160;

// ECir00_at:45-107。同敌 async：每轮抽一次自机角扰动，整波共用该角。
async sub fire_volley() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var speed0: fx = 1fx;
    var speed1: fx = 1fx;
    var jitter: fx = 1820fx;
    var volleys: int = 20;
    var gap: int = 10;
    // 0048-0051：!EN wait(10)；!E wait(30)（Easy 两段相加）
    if rank == RANK_EASY {
        wait(40);
    } else if rank == RANK_NORMAL {
        wait(10);
    }
    // 0056-0076：层数 1/1/1/2；首速 1/1/2/2，末速 1
    // 0083-0092：角扰动 ±1°(Easy) / ±10°，第二角 spread 10° 用于层偏
    // diffI($B,...) 循环 1/2/4/20 次；每轮等待 70/70/30/10（0094-0103）
    if rank == RANK_EASY {
        jitter = 182fx;
        volleys = 1;
        gap = 70;
    } else if rank == RANK_NORMAL {
        volleys = 2;
        gap = 70;
    } else if rank == RANK_HARD {
        speed0 = 2fx;
        volleys = 4;
        gap = 30;
    } else {
        speed0 = 2fx;
        layers = 2;
        volleys = 20;
        gap = 10;
    }
    var su: fx = 0fx;
    var a: angle = 0deg;
    var a1: angle = 0deg;
    for k in 0..volleys {
        // RANDF2 每轮抽一次，各层共用同一基准角
        su = (rand(65536) - 32768) as fx / 32768;
        a = aim_player() + ((jitter * su) as int) as angle;
        // 层 0：alpha + R(0) + 0*delta；EX ANIM a=1 的出生退位移 -4*velocity
        _ = fire(TH16_BALL, 6, $self_x - 4fx * speed0 * cos(a),
                 $self_y - 4fx * speed0 * sin(a), speed0, a, none, none);
        // 层 1（仅 Lunatic，etCount 层数 2）：speed1、alpha + delta(10°)
        if layers > 1 {
            a1 = a + 1820bam;
            _ = fire(TH16_BALL, 6, $self_x - 4fx * speed1 * cos(a1),
                     $self_y - 4fx * speed1 * sin(a1), speed1, a1, none, none);
        }
        wait(gap);
    }
}

// ECir00:8-43。出生框、REL 随机摆动、60 帧后开火、再 60 帧朝 (0,191) 起步。
// 0025 movePosRel 的 ±16 出生偏移由创建方在出生坐标上施加（见 pattern）。
async sub minion(px: fx, py: fx) {
    set_invuln(65535);
    set_hurtbox(12fx); // 500/501 普通圆形分支取第一值×0.5：24→12、16→8
    set_hitbox(8fx);
    // 0018 flagSet(15) 含 0x2：体碰在出生摆动期间关闭
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // 0026 movePosRelTime(60,1,0,0)：REL 60 帧二次加速回到 0
    move_to(60, px, py, EASE_QUAD_IN);
    wait(60);
    // 0028-0032：dropSeason 属奖励省略；flagClear(15) 恢复体碰
    set_enemy_flag(ENEMY_NO_BODY, 0);
    spawn fire_volley();
    wait(60);
    // 0034-0036：朝 (0,191) 定角，速度 120 帧线性 0→3
    var aim: angle = atan2(191fx - $self_y, 0fx - $self_x);
    move_vel(0, aim, 0fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    // 0037-0041：wait(1000) 无限循环，敌不自行退场
    loop { wait(1000); }
}

// MainSub02:1212-1240：两轮各 32 只，圆周角每只 ±20°、半径每只 +5
async sub pattern() {
    var ang: angle = 90deg; // 1.570796 rad
    var rad: fx = 0fx;
    var x: fx = 0fx;
    var y: fx = 0fx;
    var ox: fx = 0fx;
    var oy: fx = 0fx;
    wait(OPENING_BUFFER);
    for i in 0..SPAWN_COUNT {
        x = rad * cos(ang);
        y = rad * sin(ang) + 192fx;
        // ECir00:0025 movePosRel(RANDF2*16, RANDF2*16)：先抽 x 再抽 y
        ox = (rand(65536) - 32768) as fx / 32768;
        oy = (rand(65536) - 32768) as fx / 32768;
        _ = spawn_enemy(x + ox * 16fx, y + oy * 16fx, 70, 0, 1000, 0, minion(x, y));
        ang = ang + 20deg; // +0.349066 rad
        rad = rad + 5fx;
        wait(SPAWN_GAP);
    }
    wait(GROUP_GAP);
    ang = 90deg;
    rad = 0fx;
    for j in 0..SPAWN_COUNT {
        x = rad * cos(ang);
        y = rad * sin(ang) + 192fx;
        ox = (rand(65536) - 32768) as fx / 32768;
        oy = (rand(65536) - 32768) as fx / 32768;
        _ = spawn_enemy(x + ox * 16fx, y + oy * 16fx, 70, 0, 1000, 0, minion(x, y));
        ang = ang - 20deg;
        rad = rad + 5fx;
        wait(SPAWN_GAP);
    }
    wait(GROUP_GAP);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
